#include <stdio.h>
#include <stdlib.h>

int collatz(int n) {
    int steps = 0;
    while (n != 1) {
        if (n % 2 == 0) {
            n = n / 2;
        } else {
            n = 3 * n + 1;
        }
        steps++;
        if (steps > 1000000) {
            printf("STEP_LIMIT_EXCEEDED\n");
            return steps;
        }
        if (n > 1000000000) {
            printf("OUT_OF_RANGE\n");
            return steps;
        }
    }
    return steps;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("NO_INPUT\n");
        return 0;
    }
    char *endptr;
    long n = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        printf("BAD_INPUT\n");
        return 0;
    }
    if (n < 1) {
        printf("OUT_OF_RANGE\n");
        return 0;
    }
    int steps = collatz(n);
    printf("n=%ld steps=%d\n", n, steps);
    return 0;
}
